import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz a candidate new owner address. The reference contract's owner() must
    // always report the stored owner after transferring ownership via transferOwnership,
    // for any input newOwner (including zero-address which transferOwnership forbids).
    // The mutant changes owner() semantics and will return address(0) for some stored owners,
    // so this property will fail on the mutant for some fuzzed inputs.
    function testFuzz_property(address newOwner) public {
        // Keep domain wide but avoid unnecessary revert from transferOwnership when newOwner == address(0)
        // transferOwnership explicitly requires non-zero new owner, so only fuzz non-zero addresses
        vm.assume(newOwner != address(0));

        // Only the current owner can call transferOwnership. setUp() made deployer the owner (address(this) as constructor used _msgSender()).
        // Use prank as that owner (address(this) inside test is the test contract, which is the deployer/owner).
        // Call transferOwnership on c to set owner to newOwner.
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Read back owner via public getter. This is the single assertion: for the correct contract,
        // owner() must equal the stored owner which should be newOwner after the call above.
        assertTrue(c.owner() == newOwner);
    }
}

