pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz a candidate newOwner and check that after transferring ownership to it (via owner-only setCaller workflow)
    // the public owner() getter returns exactly the stored owner address.
    // We must fuzz at least one parameter: an address newOwner to which ownership will be transferred by the contract owner.
    function testFuzz_property(address newOwner) public {
        // Keep domain wide but avoid the zero-address transfer which Ownable forbids in transferOwnership
        // (we let the fuzzer choose zero too; in that case transferOwnership will revert and we skip the transfer).

        // We will call setCaller which is onlyOwner; the deploying address (this) is owner initially per constructor.
        // Use vm.prank to act as the deployer/owner (address(this) already is owner and we are executing in its context),
        // so no prank is actually necessary. But to be explicit, use vm.startPrank on address(this).

        vm.startPrank(address(this));
        bool transferSucceeded = true;
        // attempt to transfer ownership via transferOwnership from Ownable (inherited by C)
        // If newOwner is zero, transferOwnership reverts — that's admissible input; we detect and note failure.
        try c.transferOwnership(newOwner) {
            transferSucceeded = true;
        } catch {
            transferSucceeded = false;
        }
        vm.stopPrank();

        // Now read the owner() public getter.
        address reportedOwner = c.owner();

        // Single assertion: If transfer succeeded, then reportedOwner must equal newOwner (the stored owner)
        // If transfer failed (reverted), reportedOwner must still be the deployer (address(this)).
        // This is a single boolean expression covering both admissible outcomes.
        bool ok;
        if (transferSucceeded) {
            ok = (reportedOwner == newOwner);
        } else {
            ok = (reportedOwner == address(this));
        }

        assertTrue(ok);
    }
}

