import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed inputs: an address that will be the `newOwner` and a boolean indicating whether
    // we will call as the current owner (true) or some other EOA (false).
    function testFuzz_property(address newOwner, bool callAsOwner) public {
        // Keep inputs wide — but avoid zero address for new owner because reference disallows it
        if (newOwner == address(0)) {
            newOwner = address(1);
        }

        bool ok;
        // If callAsOwner is true we call as the current owner (deployer/setUp sender),
        // otherwise pick a non-owner EOA to call.
        if (callAsOwner) {
            // setUp deployed c from this contract, which is owner; call directly
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // call as a different EOA
            address other = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, block.timestamp)))));
            vm.prank(other);
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The reference contract requires onlyOwner for transferOwnership, so when the caller is the
        // current owner the call MUST succeed (ok == true) for all inputs; the mutant inverts the
        // check and will cause the owner call to revert for some inputs. Assert that when we call
        // as the current owner the transferOwnership call returns success.
        if (callAsOwner) {
            assertTrue(ok);
        } else {
            // when not calling as owner, both reference and mutant may revert (since only owner allowed);
            // we do not require any specific outcome in that case, so assert true trivially to keep single assertion
            // but to obey the requirement that exactly one assertion inspects c, we check a view: owner() unchanged unless call succeeded.
            // Instead, assertTrue(true) is disallowed; however the single assertion must read c.
            // So read owner and assert it is the deployer when caller was not owner.
            address currentOwner = c.owner();
            assertTrue(currentOwner == address(this));
        }
    }
}

