    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter is an arbitrary address (the fuzzer will supply many values)
    // We include at least one parameter as required. The actual distinguishing input
    // is the stored name inside the contract (set at construction). We read it via
    // c.name() and check it matches the contract's stored name getter behavior
    // (the reference returns that stored name; the mutant returns a fixed literal
    // and will thus differ for at least some runs).
    function testFuzz_property(address /*unused but fuzzed*/) public {
        // No vm.* cheatcodes used. We simply call the public getter and ensure
        // that it equals the token name we expect (the constructor argument used
        // in reference contract is "DCF Token"). The reference returns that
        // exact string; the mutant returns "MUTATED_NAME" and so will fail.

        bool ok;
        try c.name() returns (string memory v) {
            // success path: we observed name() returned v
            // Check it equals the expected constructed name
            ok = (keccak256(abi.encodePacked(v)) == keccak256(abi.encodePacked("DCF Token")));
        } catch {
            // If it reverted (should not), treat as failure
            ok = false;
        }

        // Single assertion: the reference contract always satisfies this (returns "DCF Token");
        // the mutant that returns "MUTATED_NAME" will make this assert fail for inputs
        // where name() is called (fuzzer supplied address param unused, just to satisfy
        // the requirement of at least one fuzz parameter).
        assertTrue(ok);
    }
}

