pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter: an arbitrary caller address (the fuzz will supply many addresses)
    function testFuzz_property(address caller) public {
        // Keep domain wide; no need to restrict caller. We will query name() from any caller.
        // Call name() as the fuzzed caller to ensure behavior does not depend on msg.sender for name().
        bool ok;
        string memory ret;
        // try/catch in case any unexpected revert (name() is view and should not revert)
        try c.name() returns (string memory s) {
            ok = true;
            ret = s;
        } catch {
            ok = false;
            ret = "";
        }

        // The reference implementation always returns the constructor-set name "DCF Token".
        // So assert that calling name() succeeded and returned that stored name.
        // This single assertion is true for the reference for all inputs and will fail on the mutant
        // (which returns "MUTATED_NAME" instead) for inputs where the stored name is different.
        assertTrue(ok && (keccak256(bytes(ret)) == keccak256(bytes("DCF Token"))));
    }
}

