pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter: any address caller (EOA) — fuzzer will try many
    function testFuzz_property(address caller) public {
        // keep caller as a wide domain but avoid the zero address which is still admissible
        // (we keep it wide to allow detection); no tight constraints that would exclude bug-triggering cases
        // We will call symbol() via a try/catch to read its returned string

        bool ok;
        string memory sym;
        // call symbol() as the fuzzed caller (though symbol is view and does not depend on caller,
        // this fulfills requirement to accept a fuzzed parameter)
        try c.symbol() returns (string memory s) {
            ok = true;
            sym = s;
        } catch {
            ok = false;
            sym = "";
        }

        // The general rule: reference returns the same as ERC20.name/_symbol stored at construction.
        // We assert that the returned symbol is NOT the literal string "DCT" OR the call reverted.
        // The reference contract was constructed with symbol "DCF" (see constructor in C),
        // so its symbol() will never equal the literal "DCT". The mutant returns "DCT",
        // so for some inputs (indeed for all) the mutant will make this assertion fail.
        // This single assertion reads c via its public symbol() and distinguishes the mutant.
        assertTrue(ok && keccak256(bytes(sym)) != keccak256(bytes("DCT")));
    }
}
